// Minimal deterministic multi-tenant agent runtime, used only as a research fixture (Issue #82).
//
// It is NOT a model of any real product. It reproduces the *shapes* of isolation bugs that have
// been reported publicly against real runtimes (see ../DEFECTS.md), so that test methods can be
// compared on known ground truth. There is no language model: an "agent turn" is a scripted
// action. Tenant identity comes only from a trusted token map, never from the action itself.
//
// Each defect variant is generated by replacing exactly one marked line (see ../defects.json).
// Lines carrying a `// @anchor:<name>` comment are the only lines a defect may change.

import { appendFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export interface Auth { tenantToken: string; user: string; botId: string }
export interface Session { tenant: string; user: string; botId: string; key: string }

export type Action =
  | { op: 'remember'; text: string }
  | { op: 'recall' }
  | { op: 'history' }
  | { op: 'summarize'; topic: string }
  | { op: 'get_record'; id: string; tenant_id?: string }
  | { op: 'delegate'; task: Action }
  | { op: 'artifact'; name: string; text: string }
  | { op: 'list_artifacts' }
  | { op: 'read_logs' }
  | { op: 'consolidate' };

// What the runtime's own documentation/settings claim. Baseline V1 reads only this.
export const ISOLATION_SETTINGS = {
  memory: 'per-tenant',
  sessionKey: 'bot+tenant+user',
  cache: 'tenant-keyed',
  tools: 'tenant-from-session',
  delegation: 'inherit-session',
  artifacts: 'per-tenant',
  logs: 'per-tenant',
  providerClient: 'per-tenant',
  consolidation: 'per-tenant',
  unauthenticated: 'deny',
} as const;

const DEFAULT_TENANT = 'default';

class MemoryClient {
  readonly dir: string;
  constructor(dir: string) { this.dir = dir; }
  private file(): string { return join(this.dir, 'MEMORY.md'); }
  write(text: string): void {
    mkdirSync(this.dir, { recursive: true });
    appendFileSync(this.file(), text + '\n');
  }
  read(): string[] {
    return existsSync(this.file()) ? readFileSync(this.file(), 'utf8').split('\n').filter(Boolean) : [];
  }
}

export class Runtime {
  readonly sessions = new Map<string, string[]>(); // session key -> transcript
  readonly cache = new Map<string, string>(); // cache key -> cached summary
  readonly clients = new Map<string, MemoryClient>();
  private pinnedClient: MemoryClient | undefined;
  private pinnedArtifactsDir: string | undefined;

  readonly root: string;
  private readonly tokens: Record<string, string>;
  private readonly records: Record<string, Record<string, string>>;

  constructor(root: string, tokens: Record<string, string>, records: Record<string, Record<string, string>>) {
    this.root = root;
    this.tokens = tokens;
    this.records = records;
  }

  openSession(auth: Auth): Session {
    const tenant = this.tokens[auth.tenantToken];
    if (!tenant) throw new Error('unauthenticated: no verifiable tenant context'); // deny by default
    return { tenant, user: auth.user, botId: auth.botId, key: this.sessionKey(auth.botId, tenant, auth.user) };
  }

  sessionKey(botId: string, tenant: string, user: string): string {
    return `${botId}:${tenant}:${user}`; // @anchor:session-key
  }

  tenantDir(tenant: string): string { return join(this.root, 'tenants', tenant); }

  memoryDir(s: Session): string {
    return join(this.tenantDir(s.tenant), 'memories'); // @anchor:memory-dir
  }

  memoryClient(s: Session): MemoryClient {
    const dir = this.memoryDir(s);
    let c = this.clients.get(dir); if (!c) { c = new MemoryClient(dir); this.clients.set(dir, c); } return c; // @anchor:memory-client
  }

  artifactsDir(s: Session): string {
    return join(this.tenantDir(s.tenant), 'artifacts'); // @anchor:artifacts-dir
  }

  logFile(s: Session): string {
    return join(this.tenantDir(s.tenant), 'logs', 'agent.log'); // @anchor:log-file
  }

  consolidationFile(s: Session): string {
    return join(this.tenantDir(s.tenant), 'consolidation', 'recent.log'); // @anchor:consolidation-file
  }

  cacheKey(s: Session, topic: string): string {
    return `${s.tenant}:${topic}`; // @anchor:cache-key
  }

  recordTenant(s: Session, a: { tenant_id?: string }): string {
    if (a.tenant_id !== undefined && a.tenant_id !== s.tenant) return ''; // @anchor:record-tenant
    return s.tenant;
  }

  childSession(s: Session): Session {
    return { ...s, key: `${s.key}:child` }; // @anchor:child-session
  }

  private log(s: Session, a: Action): void {
    const f = this.logFile(s);
    mkdirSync(join(f, '..'), { recursive: true });
    appendFileSync(f, `${s.key} ${JSON.stringify(a)}\n`);
  }

  private transcript(s: Session, line: string): void {
    const t = this.sessions.get(s.key) ?? [];
    t.push(line);
    this.sessions.set(s.key, t);
    const f = this.consolidationFile(s);
    mkdirSync(join(f, '..'), { recursive: true });
    appendFileSync(f, line + '\n');
  }

  turn(s: Session, a: Action): string {
    this.log(s, a);
    const out = this.dispatch(s, a);
    this.transcript(s, `${JSON.stringify(a)} -> ${out}`);
    return out;
  }

  private dispatch(s: Session, a: Action): string {
    switch (a.op) {
      case 'remember': this.memoryClient(s).write(a.text); return 'ok';
      case 'recall': return this.memoryClient(s).read().join(' | ');
      case 'history': return (this.sessions.get(s.key) ?? []).join(' | ');
      case 'summarize': {
        const k = this.cacheKey(s, a.topic);
        const hit = this.cache.get(k);
        if (hit !== undefined) return hit;
        const recs = this.records[s.tenant] ?? {};
        const summary = Object.entries(recs).filter(([id]) => id.startsWith(a.topic)).map(([, v]) => v).join('; ');
        this.cache.set(k, summary);
        return summary;
      }
      case 'get_record': {
        const t = this.recordTenant(s, a);
        if (!t) return 'denied: tenant mismatch';
        return this.records[t]?.[a.id] ?? 'not found';
      }
      case 'delegate': return this.turn(this.childSession(s), a.task);
      case 'artifact': {
        const d = this.artifactsDir(s);
        mkdirSync(d, { recursive: true });
        writeFileSync(join(d, a.name), a.text);
        return 'ok';
      }
      case 'list_artifacts': {
        const d = this.artifactsDir(s);
        return existsSync(d) ? readdirSync(d).sort().map((n) => `${n}=${readFileSync(join(d, n), 'utf8')}`).join(' | ') : '';
      }
      case 'read_logs': {
        const f = this.logFile(s);
        return existsSync(f) ? readFileSync(f, 'utf8').trim().split('\n').join(' | ') : '';
      }
      case 'consolidate': {
        const f = this.consolidationFile(s);
        const lines = existsSync(f) ? readFileSync(f, 'utf8').split('\n').filter(Boolean) : [];
        for (const l of lines) this.memoryClient(s).write(`consolidated: ${l}`);
        writeFileSync(f, '');
        return `consolidated ${lines.length}`;
      }
    }
  }
}

export { DEFAULT_TENANT };
